using System;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows.Controls;
using Microsoft.Web.WebView2.Core;
using Microsoft.Web.WebView2.Wpf;
namespace Dafeiyu
{
    // Only this immutable embedded page may send terminal input. File previews
    // use a separate WebView with host messaging disabled.
    internal sealed class TerminalBrowser:Grid,IDisposable
    {
        readonly string url="https://deskpet-terminal-"+Guid.NewGuid().ToString("N")+".invalid/index.html";readonly WebView2 browser=new WebView2();readonly Action<string> input;readonly Action<short,short> resize;readonly Action drained;readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=256*1024};bool disposed;TaskCompletionSource<bool> loaded=new TaskCompletionSource<bool>();
        internal TerminalBrowser(Action<string> input,Action<short,short> resize,Action drained){this.input=input;this.resize=resize;this.drained=drained;Children.Add(browser);}
        internal async Task InitializeAsync()
        {
            WebPreviewRuntime.ConfigureNativeLoader();var environment=await CoreWebView2Environment.CreateAsync(null,Path.Combine(WebPreviewRuntime.DirectoryPath,"terminal-profile"));if(disposed)return;await browser.EnsureCoreWebView2Async(environment);if(disposed)return;var web=browser.CoreWebView2;
            web.Settings.AreHostObjectsAllowed=false;web.Settings.IsWebMessageEnabled=true;web.Settings.AreDevToolsEnabled=false;web.Settings.IsStatusBarEnabled=false;web.Settings.AreDefaultScriptDialogsEnabled=false;
            web.LaunchingExternalUriScheme+=delegate(object sender,CoreWebView2LaunchingExternalUriSchemeEventArgs e){e.Cancel=true;};web.PermissionRequested+=delegate(object sender,CoreWebView2PermissionRequestedEventArgs e){e.State=CoreWebView2PermissionState.Deny;};web.NewWindowRequested+=delegate(object sender,CoreWebView2NewWindowRequestedEventArgs e){e.Handled=true;};web.DownloadStarting+=delegate(object sender,CoreWebView2DownloadStartingEventArgs e){e.Cancel=true;};web.NavigationStarting+=delegate(object sender,CoreWebView2NavigationStartingEventArgs e){if(e.Uri!=url)e.Cancel=true;};
            web.AddWebResourceRequestedFilter("*",CoreWebView2WebResourceContext.All,CoreWebView2WebResourceRequestSourceKinds.All);web.WebResourceRequested+=delegate(object sender,CoreWebView2WebResourceRequestedEventArgs e){e.Response=e.Request.Uri==url?environment.CreateWebResourceResponse(new MemoryStream(Encoding.UTF8.GetBytes(Page())),200,"OK","Content-Type: text/html; charset=utf-8\r\nCache-Control: no-store"):environment.CreateWebResourceResponse(new MemoryStream(new byte[0]),403,"Blocked","");};
            web.WebMessageReceived+=delegate(object sender,CoreWebView2WebMessageReceivedEventArgs e){if(disposed||e.Source!=url||web.Source!=url)return;try{var value=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(e.WebMessageAsJson);object kind;if(!value.TryGetValue("type",out kind))return;string type=kind as string;if(type=="ready"){loaded.TrySetResult(true);return;}if(type=="drained"){drained();return;}object data;if(type=="input"&&value.TryGetValue("data",out data)&&data is string&&((string)data).Length<=65536)input((string)data);if(type=="resize"){object columns,rows;if(value.TryGetValue("cols",out columns)&&value.TryGetValue("rows",out rows)){int c=Convert.ToInt32(columns),r=Convert.ToInt32(rows);if(c>=2&&c<=500&&r>=2&&r<=300)resize((short)c,(short)r);}}}catch(ArgumentException){}catch(InvalidOperationException){}catch(FormatException){}catch(OverflowException){}};
            web.Navigate(url);if(await Task.WhenAny(loaded.Task,Task.Delay(15000))!=loaded.Task)throw new IOException("终端界面加载超时。 "+await web.ExecuteScriptAsync("JSON.stringify({url:location.href,ready:document.readyState,terminal:typeof Terminal,fit:typeof FitAddon,errors:window.startupErrors})"));await loaded.Task;
        }
        static string Resource(string name){using(var stream=typeof(TerminalBrowser).Assembly.GetManifestResourceStream("Dafeiyu.Terminal."+name)){if(stream==null)throw new IOException("缺少终端界面资源。");using(var reader=new StreamReader(stream,Encoding.UTF8))return reader.ReadToEnd();}}
        static string Page(){return "<!doctype html><html><head><meta charset='utf-8'><meta http-equiv='Content-Security-Policy' content=\"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; font-src data:; connect-src 'none'; frame-src 'none'; object-src 'none'; webrtc 'block'\"><script>window.startupErrors=[];window.addEventListener('error',e=>window.startupErrors.push(e.message));</script><style>"+Resource("xterm.css")+"html,body{margin:0;height:100%;overflow:hidden;background:#fff}#terminal{height:calc(100% - 16px);padding:8px 12px}.xterm .xterm-viewport{scrollbar-width:thin}</style></head><body><div id='terminal'></div><script>"+Resource("xterm.js").Replace("</script","<\\/script")+"</script><script>"+Resource("addon-fit.js").Replace("</script","<\\/script")+"</script><script>const term=new Terminal({cursorBlink:true,fontFamily:'Consolas, monospace',fontSize:13,scrollback:5000,allowProposedApi:false,theme:{background:'#ffffff',foreground:'#243044',cursor:'#315ff4',selectionBackground:'#dce7ff',black:'#243044',red:'#c43e4f',green:'#2e7d4d',yellow:'#8a6500',blue:'#315ff4',magenta:'#8d48a5',cyan:'#177a88',white:'#5c6778',brightBlack:'#626d7f',brightRed:'#b52e40',brightGreen:'#227443',brightYellow:'#806000',brightBlue:'#2457cc',brightMagenta:'#813b9b',brightCyan:'#126f80',brightWhite:'#243044'}});const fit=new FitAddon.FitAddon();term.loadAddon(fit);term.open(document.getElementById('terminal'));const send=(m)=>chrome.webview.postMessage(m);term.onData(data=>send({type:'input',data}));function size(){fit.fit();send({type:'resize',cols:term.cols,rows:term.rows});}new ResizeObserver(size).observe(document.getElementById('terminal'));chrome.webview.addEventListener('message',e=>{const m=e.data;if(m.type==='output')term.write(m.data,()=>send({type:'drained'}));if(m.type==='clear')term.clear();if(m.type==='focus'){size();term.focus();}});size();send({type:'ready'});</script></body></html>";}
        internal void Write(string data){if(!disposed&&browser.CoreWebView2!=null)browser.CoreWebView2.PostWebMessageAsJson(json.Serialize(new{type="output",data=data}));}
        internal void Clear(){if(!disposed&&browser.CoreWebView2!=null)browser.CoreWebView2.PostWebMessageAsJson("{\"type\":\"clear\"}");}
        internal void FocusInput(){if(!disposed&&browser.CoreWebView2!=null)browser.CoreWebView2.PostWebMessageAsJson("{\"type\":\"focus\"}");}
        internal Task<string> EvaluateAsync(string script){return browser.CoreWebView2.ExecuteScriptAsync(script);}
        internal Task CaptureAsync(Stream stream){return browser.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,stream);}
        public void Dispose(){if(disposed)return;disposed=true;loaded.TrySetCanceled();browser.Dispose();Children.Clear();}
    }
}
